function techImg(T) { if (T.fx.gen) return EQ_IMG[T.fx.gen[0]] || TECH_DEF_IMG[T.cat]; if (T.fx.ship) return 'sh_' + T.fx.ship.types[T.fx.ship.types.length - 1]; if (/mar$/.test(T.id)) return 'sh_tr'; if (/para/.test(T.id)) return 'f_para'; if (/mtn/.test(T.id)) return 'f_mount'; if (/hos/.test(T.id)) return 'f_nurse'; if (/code/.test(T.id)) return 'f_code'; if (/radar/.test(T.id)) return 'f_radio'; if (/syn/.test(T.id)) return 'f_oil'; if (/res\d/.test(T.id) && T.cat === 'ind') return 'f_coal'; if (/res\d/.test(T.id)) return 'f_lab'; if (/dock/.test(T.id)) return 'f_yard'; if (/con\d/.test(T.id)) return 'f_civil'; return TECH_DEF_IMG[T.cat]; }
const MOD_NAMES = { build:'Скорость стройки', prod:'Выпуск заводов', research:'Скорость исследований', pp:'Власть в день', pp_mul:'Прирост власти', stab:'Стабильность', warsup:'Поддержка войны', org:'Организация', sa:'Мягкая атака', ha:'Жёсткая атака', def:'Защита', brk:'Прорыв', arm:'Броня', spd:'Скорость войск', plan:'Планирование', ent:'Окопы', sup_use:'Расход снабжения', casualty:'Потери людей', mp_mul:'Людские ресурсы', train:'Скорость обучения', res:'Добыча ресурсов', synth:'Синтетика', eff_cap:'Предел эффективности', eff_gain:'Рост эффективности', dock_out:'Выпуск верфей', air_range:'Дальность авиации', air_det:'Обнаружение авиации', land_prep:'Подготовка десанта', dipl:'Цена дипломатии', justify:'Цена обоснования войны', ftr_atk:'Атака истребителей', cas_atk:'Атака штурмовиков', str_atk:'Сила бомбардировок', str_def:'Защита бомбардировщиков', air_sup:'Поддержка с воздуха', gun:'Корабельные орудия', dom:'Господство на море', ship_aa:'ПВО кораблей', cv_atk:'Авианосная авиация', det:'Обнаружение на море', ss_atk:'Атака подлодок', raid:'Морские рейды', repair:'Ремонт кораблей', cwidth:'Ширина атаки', fort_bonus:'Защита фортов', hill_bonus:'Бой в горах', urban_bonus:'Бой в городах', winter:'Зимняя подготовка', bomb_res:'Устойчивость к бомбардировкам', work:'Работа заводов', div_xp:'Опыт дивизий', r_inf:'Исследования пехоты', r_sup:'Исследования поддержки', r_arm:'Исследования бронетехники', r_art:'Исследования артиллерии', r_air:'Исследования авиации', r_nav:'Исследования флота', r_ind:'Исследования индустрии', r_ele:'Исследования электроники' };
function fmtMods(m) { if (!m) return ''; return Object.entries(m).map(([k, v]) => (MOD_NAMES[k] || k) + ': ' + (v > 0 ? '+' : '') + (k === 'pp' || k === 'air_range' ? v : Math.round(v * 100) + '%')).join('\n'); }
